def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]

    row_bounds = {}
    col_bounds = {}
    for r, c in marks:
        row_bounds.setdefault(r, []).append(c)
        col_bounds.setdefault(c, []).append(r)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            in_row = r in row_bounds and min(row_bounds[r]) <= c <= max(row_bounds[r])
            in_col = c in col_bounds and min(col_bounds[c]) <= r <= max(col_bounds[c])
            if in_row or in_col:
                out[r][c] = 3
    return out
